// backend/src/models/Certificate.js
const mongoose = require('mongoose');

/**
 * Certificate — issued automatically when a student's enrollment
 * reaches 100% progress. The PDF is generated by generateCertificate.js,
 * uploaded to Cloudinary, and its URL stored here.
 */
const certificateSchema = new mongoose.Schema({
  student: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'User',
    required: true,
  },
  course: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Course',
    required: true,
  },
  enrollment: {
    type: mongoose.Schema.Types.ObjectId,
    ref: 'Enrollment',
    required: true,
  },

  // Certificate metadata
  certificateId: {
    type: String,
    unique: true,
    required: true,
  },
  studentName: { type: String, required: true },
  courseTitle: { type: String, required: true },
  instructorName: { type: String, required: true },
  completedAt: { type: Date, required: true },

  // PDF stored on Cloudinary
  pdfUrl: { type: String, required: true },

  isValid: { type: Boolean, default: true }, // Admin can invalidate if needed
}, {
  timestamps: true,
});

// One certificate per student per course
certificateSchema.index({ student: 1, course: 1 }, { unique: true });

module.exports = mongoose.model('Certificate', certificateSchema);
